// Prepare base64 CSV data
const body = $input.first().json.body;
const base64Data = body.data;
const options = body.options || {};
const operation = body.operation || 'parse';
const filter = body.filter || null;
const transform = body.transform || null;

// Remove data URL prefix if present
const cleanBase64 = base64Data.replace(/^data:[^;]+;base64,/, '');

// Decode base64 to string
const csvContent = Buffer.from(cleanBase64, 'base64').toString('utf-8');

return {
  json: {
    csvContent: csvContent,
    options: options,
    operation: operation,
    filter: filter,
    transform: transform,
    startTime: Date.now()
  }
};

