const csvContent = $input.first().json;
const options = body.options || {};
const operation = body.operation || 'parse';
const filter = body.filter || null;
const transform = body.transform || null;

// Handle if response is string or has data property
let content = '';
if (typeof csvContent === 'string') {
  content = csvContent;
} else if (csvContent.data) {
