    options: options,
    operation: operation,
    filter: filter,
    transform: transform,
    startTime: Date.now()
  }
};

// Parse CSV and apply operations
const input = $input.first().json;
const csvContent = input.csvContent;
const options = input.options || {};
const operation = input.operation || 'parse';
const filter = input.filter;
const transform = input.transform;
const startTime = input.startTime;

// Detect delimiter if not specified
let delimiter = options.delimiter || ',';
if (!options.delimiter) {
  const firstLine = csvContent.split('\n')[0] || '';
  if (firstLine.includes(';') && !firstLine.includes(',')) {
    delimiter = ';';
  } else if (firstLine.includes('\t')) {
    delimiter = '\t';
  }
}

// Remove BOM if present
let content = csvContent;
if (content.charCodeAt(0) === 0xFEFF) {
  content = content.slice(1);
}

// Split into lines
const lines = content.split(/\r?\n/).filter(line => line.trim());
if (lines.length === 0) {
  return {
    json: {
      success: true,
      data: {
        rows: [],
        columns: [],
        row_count: 0,
        operation_applied: operation
      },
      meta: {
        provider: 'n8n-native',
        execution_mode: 'online',
        processing_time_ms: Date.now() - startTime
      }
    }
  };
}

// Parse CSV with proper quote handling
function parseCSVLine(line, delim) {
  const result = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    const nextChar = line[i + 1];

    if (char === '"') {
      if (inQuotes && nextChar === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === delim && !inQuotes) {
      result.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }
  result.push(current.trim());
  return result;
}

// Get headers and data
const hasHeader = options.has_header !== false;
let columns = [];
let dataLines = [];

if (hasHeader) {
  columns = parseCSVLine(lines[0], delimiter);
  dataLines = lines.slice(1);
} else {
  const firstRow = parseCSVLine(lines[0], delimiter);
  columns = firstRow.map((_, i) => `column_${i + 1}`);
  dataLines = lines;
}

// Parse all rows
let rows = dataLines.map(line => {
  const values = parseCSVLine(line, delimiter);
  const row = {};
  columns.forEach((col, i) => {
    row[col] = values[i] || '';
  });
  return row;
});

// Apply filter operation
if (operation === 'filter' && filter) {
  const { column, operator, value } = filter;
  rows = rows.filter(row => {
    const cellValue = row[column];
    if (cellValue === undefined) return false;

    switch (operator) {
      case 'equals':
        return cellValue === value;
      case 'contains':
        return cellValue.toString().includes(value);
      case 'gt':
        return parseFloat(cellValue) > parseFloat(value);
      case 'lt':
        return parseFloat(cellValue) < parseFloat(value);
      case 'gte':
        return parseFloat(cellValue) >= parseFloat(value);
      case 'lte':
        return parseFloat(cellValue) <= parseFloat(value);
      case 'not_equals':
        return cellValue !== value;
      default:
        return true;
    }
  });
}

// Apply transform operation
if (operation === 'transform' && transform) {
  // Select specific columns
  if (transform.select_columns && transform.select_columns.length > 0) {
    columns = transform.select_columns.filter(col => columns.includes(col));
    rows = rows.map(row => {
      const newRow = {};
      columns.forEach(col => {
        newRow[col] = row[col];
      });
      return newRow;
    });
  }

  // Rename columns
  if (transform.rename) {
    const renames = transform.rename;
    columns = columns.map(col => renames[col] || col);
    rows = rows.map(row => {
      const newRow = {};
      Object.keys(row).forEach(key => {
        const newKey = renames[key] || key;
        newRow[newKey] = row[key];
      });
      return newRow;
    });
  }
}

// Apply aggregate operation
if (operation === 'aggregate') {
  const aggregations = {};
  columns.forEach(col => {
    const values = rows.map(r => parseFloat(r[col])).filter(v => !isNaN(v));
    if (values.length > 0) {
      aggregations[col] = {
        count: rows.length,
        numeric_count: values.length,
        sum: values.reduce((a, b) => a + b, 0),
        avg: values.reduce((a, b) => a + b, 0) / values.length,
        min: Math.min(...values),
        max: Math.max(...values)
      };
    } else {
      aggregations[col] = {
        count: rows.length,
        numeric_count: 0,
        unique_values: [...new Set(rows.map(r => r[col]))].length
      };
    }
  });

  return {
    json: {
      success: true,
      data: {
        aggregations: aggregations,
        columns: columns,
        row_count: rows.length,
        operation_applied: operation
      },
      meta: {
        provider: 'n8n-native',
        execution_mode: 'online',
        processing_time_ms: Date.now() - startTime,
        delimiter_detected: delimiter
      }
    }
  };
}

return {
  json: {
    success: true,
    data: {
      rows: rows,
      columns: columns,
      row_count: rows.length,
      operation_applied: operation
    },
    meta: {
      provider: 'n8n-native',
      execution_mode: 'online',
      processing_time_ms: Date.now() - startTime,
      delimiter_detected: delimiter,
      has_header: hasHeader
    }
  }
};

